/**
 * Static brand assets for invoice rendering.
 *
 * INVOICE_LOGO_PNG_BASE64 is `public/assets/logo-stamp.png` (the Stamp.ai
 * serif wordmark, 526x160, transparent background) inlined so the PDF
 * renderer can embed it without network or filesystem access.
 * Regenerate with: base64 -i public/assets/logo-stamp.png | tr -d '\n'
 */

export const INVOICE_LOGO_WIDTH = 526;
export const INVOICE_LOGO_HEIGHT = 160;

/**
 * Absolute URL of the wordmark for the HTML email body. Most email clients
 * block data: URIs in images, so the email references the hosted file.
 */
export function getInvoiceLogoUrl(): string {
  const siteUrl = Deno.env.get("SITE_URL") || "http://localhost:3000";
  return `${siteUrl.replace(/\/+$/, "")}/assets/logo-stamp.png`;
}

export const INVOICE_LOGO_PNG_BASE64 =
  "";
